list_tax_rules.code:
var response = await client.TaxRules.ListTaxRulesAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var taxRule in ((IReadOnlyList<object?>)body["tax_rules"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{taxRule["id"]} {taxRule["name"]} {taxRule["default"]}");

create_tax_rule.code:
var response = await client.TaxRules.CreateTaxRuleAsync(new Dictionary<string, object?>
{
    ["tax_rule"] = new Dictionary<string, object?> { ["name"] = "Reduced rate", ["description"] = "Rule for reduced-rate goods" },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxRule = (IReadOnlyDictionary<string, object?>)body["tax_rule"]!;
Console.WriteLine(taxRule["id"]);

get_tax_rule.code:
var response = await client.TaxRules.GetTaxRuleAsync(7);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxRule = (IReadOnlyDictionary<string, object?>)body["tax_rule"]!;
Console.WriteLine(taxRule["name"]);
foreach (var zone in ((IReadOnlyList<object?>)taxRule["zones"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{zone["id"]} {zone["name"]}");

